<?php require dirname(__DIR__).'/app/bootstrap.php';$me=require_login();require_permission('homepage.manage');$error='';$allowed=['lead','secondary_1','secondary_2','secondary_3','secondary_4','investigation','visual_feature','opinion'];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();try{$slot=(string)($_POST['slot_key']??'');$articleId=(int)($_POST['article_id']??0);$starts=trim((string)($_POST['starts_at']??''));$ends=trim((string)($_POST['ends_at']??''));$starts=$starts?date('Y-m-d H:i:s',strtotime($starts)):null;$ends=$ends?date('Y-m-d H:i:s',strtotime($ends)):null;if(!in_array($slot,$allowed,true))throw new RuntimeException('Invalid homepage slot.');$article=$articleId?query_one("SELECT id,type FROM articles WHERE id=? AND status='published'",[$articleId]):null;if($articleId&&!$article)throw new RuntimeException('Only published articles may be curated.');if($article&&$slot==='visual_feature'&&!in_array($article['type'],['video','photo'],true))throw new RuntimeException('The visual feature slot accepts only video or photo stories.');if($article&&$slot==='investigation'&&$article['type']!=='investigation')throw new RuntimeException('The investigation slot accepts only investigation stories.');if($article&&$slot==='opinion'&&!in_array($article['type'],['opinion','editorial'],true))throw new RuntimeException('The opinion slot accepts only opinion or editorial stories.');if($starts&&$ends&&strtotime($ends)<=strtotime($starts))throw new RuntimeException('End time must follow start time.');if(db_is_sqlite())db()->prepare('INSERT INTO homepage_slots(slot_key,article_id,starts_at,ends_at,updated_by,updated_at) VALUES (?,?,?,?,?,datetime(\'now\')) ON CONFLICT(slot_key) DO UPDATE SET article_id=excluded.article_id,starts_at=excluded.starts_at,ends_at=excluded.ends_at,updated_by=excluded.updated_by,updated_at=datetime(\'now\')')->execute([$slot,$articleId?:null,$starts,$ends,(int)$me['id']]);else db()->prepare('INSERT INTO homepage_slots(slot_key,article_id,starts_at,ends_at,updated_by) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE article_id=VALUES(article_id),starts_at=VALUES(starts_at),ends_at=VALUES(ends_at),updated_by=VALUES(updated_by)')->execute([$slot,$articleId?:null,$starts,$ends,(int)$me['id']]);audit_log('homepage_slot_update','homepage_slot',0,$slot.':'.($articleId?:'empty'));flash('Homepage slot updated and audited.');header('Location: '.path('admin/homepage-manager.php'));exit;}catch(Throwable $e){$error=$e->getMessage();}}
$slots=query_all('SELECT h.*,a.title,u.full_name FROM homepage_slots h LEFT JOIN articles a ON a.id=h.article_id LEFT JOIN users u ON u.id=h.updated_by ORDER BY h.slot_key');$byKey=[];foreach($slots as $s)$byKey[$s['slot_key']]=$s;$articles=query_all("SELECT id,title,published_at FROM articles WHERE status='published' ORDER BY published_at DESC LIMIT 300");
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Homepage Manager · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="admin-body"><main class="admin-content" style="max-width:1200px;margin:auto"><p><a href="<?=e(path('admin/index.php'))?>">← Newsroom</a> · <a href="<?=e(path())?>" target="_blank" rel="noopener">Preview public homepage ↗</a></p><div class="admin-section-title"><h1>Homepage manager<span class="brand-accent">.</span></h1></div><p>Only already-published stories are eligible. Empty or expired slots fall back to the chronological homepage.</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice"><?=e($msg)?></div><?php endif;?><div class="workflow-grid"><?php foreach($allowed as $slot):$current=$byKey[$slot]??null;?><section class="setting-panel"><h2><?=e(str_replace('_',' ',strtoupper($slot)))?></h2><?php if($current&&$current['title']):?><p><b><?=e($current['title'])?></b><br><small>Updated by <?=e($current['full_name']??'Unknown')?> · <?=e(display_date($current['updated_at']))?></small></p><?php endif;?><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="slot_key" value="<?=e($slot)?>"><label>STORY<select name="article_id"><option value="0">Use automatic fallback</option><?php foreach($articles as $a):?><option value="<?=$a['id']?>" <?=($current['article_id']??0)==$a['id']?'selected':''?>><?=e($a['title'])?></option><?php endforeach;?></select></label><label>STARTS<input type="datetime-local" name="starts_at" value="<?=e(!empty($current['starts_at'])?date('Y-m-d\TH:i',strtotime($current['starts_at'])):'')?>"></label><label>ENDS<input type="datetime-local" name="ends_at" value="<?=e(!empty($current['ends_at'])?date('Y-m-d\TH:i',strtotime($current['ends_at'])):'')?>"></label><button>UPDATE SLOT →</button></form></section><?php endforeach;?></div></main></body></html>
